WITH t AS (
  SELECT user_id, SUM(amount) AS monetary FROM purchases GROUP BY user_id
),
g AS (
  SELECT user_id, monetary, NTILE(3) OVER (ORDER BY monetary DESC, user_id) AS m_group FROM t
)
SELECT m_group, COUNT(*) AS users, SUM(monetary) AS revenue
FROM g
GROUP BY m_group
ORDER BY m_group;
